tretch","items":[{"id":"col-solutions-heading","width":"1fr","modules":[{"id":"heading-solutions","type":"heading","props":{"anchor":"","eyebrow":"حلول متكاملة","title":"كل ما يحتاجه مركزك لينمو بثقة","body":"ابدأ من احتياج واحد أو فعّل المنظومة كاملة؛ جميع الوحدات تعمل على نفس البيانات وتتوسع معك.","level":"h2"},"style":{"variant":"light","align":"center","paddingY":18,"maxWidth":"reading","background":"","color":"","borderColor":"","borderWidth":0,"borderRadius":0,"shadow":"none","animation":"none","animationDelay":0,"cssClass":"mt-section-title"},"responsive":{"hideDesktop":false,"hideTablet":false,"hideMobile":false}}],"style":{"background":"","color":"","padding":0,"gap":14,"borderColor":"","borderWidth":0,"borderRadius":0,"shadow":"none","verticalAlign":"stretch"},"responsive":{"hideDesktop":false,"hideTablet":false,"hideMobile":false}}]},"style":{"variant":"light","align":"center","paddingY":75,"maxWidth":"wide","background":"","color":"","borderColor":"","borderWidth":0,"borderRadius":0,"shadow":"none","animation":"none","animationDelay":0,"cssClass":"mt-solutions-heading-row"},"responsive":{"hideDesktop":false,"hideTablet":false,"hideMobile":false}}]$blocks$::jsonb,
    true
  );
  v_document:=private_app.website_builder_validate_document(v_document);

  update website.pages set content=v_document,updated_at=now() where id=v_page_id;
  update website.content_documents
  set draft_document=v_document,published_document=v_document,
      draft_updated_at=now(),published_at=now(),updated_at=now()
  where site_id=v_site_id and entity_type='page' and entity_id=v_page_id;
end
$$;
commit;
